package com.nigson.acceptance.market;
import com.nigson.commerce.market.*;
import com.nigson.shared.events.EventCodec;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;
class MarketValuesTest {
 @Test void currencyAndDisabledCreationAreClosedWithoutPolicies(){var input=EventCodec.JSON.readTree("{\"code\":\"NG\",\"name\":\"Nigeria\",\"currency\":\"NGN\"}");assertThat(MarketValues.create(input).currency()).isEqualTo("NGN");for(String field:List.of("enabled","taxPolicy","destinations","minorUnit","actor")){var copy=(tools.jackson.databind.node.ObjectNode)input.deepCopy();copy.put(field,true);assertThatThrownBy(()->MarketValues.create(copy)).hasMessage("VALIDATION_ERROR");}var copy=(tools.jackson.databind.node.ObjectNode)input.deepCopy();copy.put("currency","ZZZ");assertThatThrownBy(()->MarketValues.create(copy)).hasMessage("VALIDATION_ERROR");}
 @Test void explicitTaxRatesRequireClosedApprovedSchemaAndNoAssumedZero(){assertThatThrownBy(()->MarketValues.tax(EventCodec.JSON.readTree("{}"))).hasMessage("VALIDATION_ERROR");var input=EventCodec.JSON.readTree("{\"schemaVersion\":1,\"mode\":\"NONE\",\"rate\":\"0\",\"rounding\":\"HALF_UP\",\"approvalReference\":\"SYNTHETIC_OFFLINE_POLICY_ONLY\"}");assertThat(MarketValues.tax(input).rate()).isZero();for(String rate:List.of("0.1","1.01","-1","1e-2")){var copy=(tools.jackson.databind.node.ObjectNode)input.deepCopy();copy.put("rate",rate);assertThatThrownBy(()->MarketValues.tax(copy)).hasMessage("VALIDATION_ERROR");}var copy=(tools.jackson.databind.node.ObjectNode)input.deepCopy();copy.put("approvalReference","");assertThatThrownBy(()->MarketValues.tax(copy)).hasMessage("VALIDATION_ERROR");}
 @Test void addressPatternsUseBoundedLinearEngineAndRejectUnsupportedExpressions(){var input=EventCodec.JSON.readTree("{\"schemaVersion\":1,\"requiredFields\":[\"RECIPIENT\",\"PHONE\",\"LINE1\",\"CITY\"],\"postalPattern\":\"^[0-9]{6}$\",\"regionCodes\":[]}");assertThatCode(()->MarketValues.address(input)).doesNotThrowAnyException();for(String pattern:List.of("^(?=a)a$","^(a)\\1$","^x{99,1}$")){var copy=(tools.jackson.databind.node.ObjectNode)input.deepCopy();copy.put("postalPattern",pattern);assertThatThrownBy(()->MarketValues.address(copy)).hasMessage("VALIDATION_ERROR");}var missing=(tools.jackson.databind.node.ObjectNode)input.deepCopy();missing.set("requiredFields",EventCodec.JSON.valueToTree(List.of("CITY","CITY")));assertThatThrownBy(()->MarketValues.address(missing)).hasMessage("VALIDATION_ERROR");}
 @Test void closedMetricTagsExcludeBusinessIdentifiers(){var metrics=new io.micrometer.core.instrument.simple.SimpleMeterRegistry();metrics.config().meterFilter(new com.nigson.commerce.platform.MetricPolicy());metrics.counter("nigson.market.commands","operation","BOOK").increment();metrics.counter("nigson.market.commands","operation",UUID.randomUUID().toString()).increment();assertThat(metrics.getMeters()).hasSize(1);}
}
